import zipfile
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

with zipfile.ZipFile("budget.xlsx") as z:
    wb_xml = ET.fromstring(z.read("xl/workbook.xml"))
    sheet = wb_xml.find(".//m:sheets/m:sheet", NS)
    print("Sheet name:", sheet.get("name"), "| sheetId:", sheet.get("sheetId"))

    root = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    print("dims:", root.find("m:dimension", NS).get("ref"))

    for row in root.findall(".//m:sheetData/m:row", NS):
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            is_ = c.find("m:is", NS)
            if v is not None:
                val = v.text
            elif is_ is not None:
                val = "".join(t.text or "" for t in is_.findall(".//m:t", NS))
            else:
                val = None
            if val is not None:
                print(f"{ref} (t={t}): {val!r}")

import zipfile
import xml.etree.ElementTree as ET
from collections import OrderedDict

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

with zipfile.ZipFile("budget.xlsx") as z:
    root = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))

items = []
for row in root.findall(".//m:sheetData/m:row", NS):
    cells = {}
    for c in row.findall("m:c", NS):
        v = c.find("m:v", NS)
        is_ = c.find("m:is", NS)
        if v is not None:
            cells[c.get("r")[0]] = v.text
        elif is_ is not None:
            cells[c.get("r")[0]] = "".join(t.text or "" for t in is_.findall(".//m:t", NS))
    # expense rows: col A=category, col B=item, col C=amount
    if "A" in cells and "C" in cells and cells["A"] != "EXPENSES" and cells["A"] != "Total Expenses":
        items.append((cells["A"], cells["B"], float(cells["C"])))

print("Parsed expense items:")
per_cat = OrderedDict()
for cat, item, amt in items:
    print(f"  {cat:15s} {item:20s} {amt:>10,.2f}")
    per_cat[cat] = per_cat.get(cat, 0.0) + amt

total = sum(per_cat.values())
print("\nPer-category totals:")
for cat, amt in per_cat.items():
    print(f"  {cat:15s} {amt:>10,.2f}")
print(f"\nTOTAL EXPENSES: {total:,.2f}")

